steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { search: { _and: [{ title: { contains: \"login timeout\" } } ] }, team: { key: { eq: \"WEB\" } } }) { nodes { id identifier title priority createdAt createdBy { name email } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { team: { key: { eq: \"WEB\" } } }, first: 50) { nodes { id identifier title priority createdAt creator { name email } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(input: { id: \"i-web-timeout\", priority: 4 }) { success issue { id identifier title priority } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-web-timeout\", input: { priority: 4 }) { success issue { id identifier title priority } } }"
  }'
